import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/input.css";
import "./shared/input-2.css";
import "./shared/input-group.css";
import "./input.css";

const fieldText =
  "w-full min-w-0 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed md:text-sm";

export type InputProps = ComponentProps<"input"> & {
  /** Fixed text or an icon before the value, e.g. "caliper.app/". */
  leading?: ReactNode;
  /** Text, an icon or a status after the value, e.g. a spinner or a count. */
  trailing?: ReactNode;
};

/**
 * A recessed text field. Fields sit slightly below the paper (an inner shade
 * and a 3:1 ring); buttons stand on it, so what you fill and what you press
 * never look alike.
 */
export function Input({ className, leading, trailing, ...props }: InputProps) {
  if (leading === undefined && trailing === undefined) {
    return (
      <input
        data-slot="input"
        className={cn("flex h-[var(--control-height)] rounded-button px-3", fieldText, className)}
        {...props}
      />
    );
  }
  return (
    <span
      data-slot="input-group"
      data-disabled={props.disabled || undefined}
      data-invalid={props["aria-invalid"] === true || props["aria-invalid"] === "true" || undefined}
      data-readonly={props.readOnly || undefined}
      className={cn("flex h-[var(--control-height)] w-full min-w-0 items-center gap-2 rounded-button px-3", className)}
    >
      {leading !== undefined && <span data-slot="input-affix">{leading}</span>}
      <input data-slot="input-bare" className={cn("h-full flex-1 bg-transparent", fieldText)} {...props} />
      {trailing !== undefined && <span data-slot="input-trailing">{trailing}</span>}
    </span>
  );
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";

export function Label({ className, ...props }: ComponentProps<"label">) {
  return (
    <label
      data-slot="label"
      className={cn(
        "inline-block max-w-full text-sm leading-5 font-medium [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { Eye } from "lucide-react";
import { useId, useState, type ComponentProps } from "react";
import { Input } from "./input";
import { Label } from "./label";
import { cn } from "./lib/cn";
import "./shared/chip-option.css";
import "./password-field.css";

export function PasswordField({
  label,
  description,
  id,
  messages,
  className,
  onFocus,
  onBlur,
  onKeyUp,
  ...props
}: {
  label: string;
  description?: string;
  messages?: { show?: string; hide?: string };
} & Omit<ComponentProps<"input">, "type">) {
  const generated = useId();
  const fieldId = id ?? generated;
  const descriptionId = `${fieldId}-description`;
  const capsId = `${fieldId}-caps`;
  const [visible, setVisible] = useState(false);
  const [caps, setCaps] = useState(false);
  const [focused, setFocused] = useState(false);
  const show = messages?.show ?? "Show password";
  const hide = messages?.hide ?? "Hide password";
  const describedBy = [description ? descriptionId : null, focused && caps ? capsId : null].filter(Boolean).join(" ") || undefined;

  return (
    <div className={cn("grid content-start gap-1.5", className)}>
      <Label htmlFor={fieldId}>{label}</Label>
      <div className="relative">
        <Input
          {...props}
          id={fieldId}
          type={visible ? "text" : "password"}
          spellCheck={false}
          autoCapitalize="off"
          autoCorrect="off"
          aria-describedby={describedBy}
          className="pr-11"
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          onKeyUp={(event) => {
            setCaps(event.getModifierState("CapsLock"));
            onKeyUp?.(event);
          }}
        />
        <button
          data-slot="password-toggle"
          type="button"
          aria-pressed={visible}
          aria-label={visible ? hide : show}
          className="absolute top-1/2 right-1 grid size-8 -translate-y-1/2 place-items-center rounded-control text-muted-foreground outline-none hover:text-foreground focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          onClick={() => setVisible((value) => !value)}
        >
          <span className="relative grid size-4 place-items-center">
            <Eye aria-hidden="true" className="size-4" />
            <span data-slot="password-slash" data-drawn={!visible} />
          </span>
        </button>
      </div>
      {description ? (
        <p id={descriptionId} className="text-xs leading-[18px] text-muted-foreground">
          {description}
        </p>
      ) : null}
      <p id={capsId} role="status" className={cn("text-xs leading-[18px] text-warning", !(focused && caps) && "sr-only")}>
        {focused && caps ? "Caps Lock is on." : ""}
      </p>
    </div>
  );
}

/* Shared by combobox.tsx, input.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="input"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Recessed to fill. One ring for every field: 3:1 at rest, darker on
     hover, a 2px ember ring with a soft halo on focus, danger when invalid.
     Disabled and read-only drop into the sunken fill and stay legible. */
  [data-slot="input"] {
    border: 0;
    background-color: var(--field);
    box-shadow: var(--shadow-field);
    transition: box-shadow var(--duration-fast) var(--ease-out);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="input"] {
      transition: none;
    }
  }
}

/* Shared by combobox.tsx, input.tsx, select-menu.tsx, select.tsx, textarea.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  @media (hover: hover) {
    :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"]):hover:enabled:not(:focus-visible):not([aria-invalid="true"]) {
      box-shadow: var(--shadow-field-hover);
    }
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"]):focus-visible {
    outline: none;
    box-shadow: var(--shadow-field-focus);
    transition: none;
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"])[aria-invalid="true"] {
    box-shadow: var(--shadow-field-invalid);
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"])[aria-invalid="true"]:focus-visible {
    box-shadow:
      var(--shadow-field-invalid),
      0 0 0 4px color-mix(in srgb, var(--danger) 18%, transparent);
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"]):disabled {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
    color: var(--muted-foreground);
  }
  :is([data-slot="input"], [data-slot="textarea"])[readonly] {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
  }
}

/* Shared by input.tsx, money-field.tsx, phone-field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  @media (hover: hover) {
    :is([data-slot="input-group"], [data-slot="money-field"], [data-slot="phone-field-control"]):not([data-disabled]):not([data-invalid]):hover:not(:focus-within) {
      box-shadow: var(--shadow-field-hover);
    }
  }
  :is([data-slot="input-group"], [data-slot="money-field"], [data-slot="phone-field-control"]):focus-within {
    outline: none;
    box-shadow: var(--shadow-field-focus);
    transition: none;
  }
}

/* input.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Recessed to fill. One ring for every field: 3:1 at rest, darker on
     hover, a 2px ember ring with a soft halo on focus, danger when invalid.
     Disabled and read-only drop into the sunken fill and stay legible. */
  [data-slot="input-group"] {
    border: 0;
    background-color: var(--field);
    box-shadow: var(--shadow-field);
    transition: box-shadow var(--duration-fast) var(--ease-out);
  }
  [data-slot="input-group"][data-invalid] {
    box-shadow: var(--shadow-field-invalid);
  }
  [data-slot="input-group"][data-invalid]:focus-within {
    box-shadow:
      var(--shadow-field-invalid),
      0 0 0 4px color-mix(in srgb, var(--danger) 18%, transparent);
  }
  [data-slot="input-group"][data-disabled] {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
    color: var(--muted-foreground);
  }
  [data-slot="input-group"][data-readonly] {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
  }
  [data-slot="input-bare"] {
    border: 0;
    box-shadow: none;
    outline: none;
  }
  [data-slot="input-affix"] {
    display: inline-flex;
    align-items: center;
    height: 20px;
    padding-inline-end: 10px;
    margin-inline-end: 2px;
    color: var(--muted-foreground);
    box-shadow: 1px 0 0 var(--border);
    white-space: nowrap;
  }
  [data-slot="input-affix"]:dir(rtl) {
    box-shadow: -1px 0 0 var(--border);
  }
  [data-slot="input-affix"]:has(> svg:only-child) {
    padding-inline-end: 0;
    box-shadow: none;
  }
  [data-slot="input-trailing"] {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--muted-foreground);
    white-space: nowrap;
    font-size: 12px;
  }
  :is([data-slot="input-affix"], [data-slot="input-trailing"]) svg {
    width: 16px;
    height: 16px;
  }
  [data-slot="docs-toolbar"] [data-slot="input-group"] { max-width: 24rem; }
}

/* Shared by calendar.tsx, chart-parts.tsx, chip-group.tsx, data-table.tsx, number-field.tsx, password-field.tsx, stepper.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Depth sets 2 and 3 end */

  /* Press feedback (2026-10-20, motion audit): every pressable control answers a press. Compact controls take the
     system press scale, as Button does; wide rows deepen their fill instead, since scaling a full-width row reads as a
     jump. Disabled controls stay still. */
  :is([data-slot="chip-option"], [data-slot="number-field"] button, [data-slot="password-toggle"], [data-slot="calendar"] button, [data-slot="chart-legend-item"], [data-slot="sort-button"], [data-slot="stepper"] button):active:not(:disabled):not([aria-disabled="true"]) {
    scale: var(--motion-press-scale);
  }
}

/* password-field.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="password-slash"] {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 1.15rem;
    height: 1.5px;
    border-radius: 1px;
    background: currentColor;
    translate: -50% -50%;
    rotate: -40deg;
    scale: 0 1;
    transition: scale var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="password-slash"][data-drawn="true"] {
    scale: 1 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="password-slash"] {
      transition: scale 400ms var(--ease-showcase);
    }
  }
}
